CREATE TABLE t1(a PRIMARY KEY, b, c); INSERT INTO t1 VALUES(0, 1, 'a'); INSERT INTO t1 VALUES(1, 0, 'b'); INSERT INTO t1 VALUES(2, 1, 'c'); INSERT INTO t1 VALUES(3, 0, 'd'); INSERT INTO t1 VALUES(4, 1, 'e'); INSERT INTO t1 VALUES(5, 0, 'a'); INSERT INTO t1 VALUES(6, 1, 'b'); INSERT INTO t1 VALUES(7, 0, 'c'); INSERT INTO t1 VALUES(8, 1, 'd'); INSERT INTO t1 VALUES(9, 0, 'e'); CREATE INDEX t1bc ON t1(b, c); CREATE TABLE t2(x, y); CREATE INDEX t2xy ON t2(x, y); WITH data(i, x, y) AS ( SELECT 0, 0, tochar(0) UNION ALL SELECT i+1, (i+1)%2, tochar(i+1) FROM data WHERE i<500 ) INSERT INTO t2 SELECT x, y FROM data; CREATE TABLE t3(x, y); INSERT INTO t3 SELECT * FROM t2; ANALYZE;
SELECT count(*) FROM t1 WHERE a IN (SELECT b FROM t1 AS ii)
SELECT count(*) FROM t1 WHERE a IN (0, 1)
SELECT count(*) FROM t2 WHERE y = 'j';
SELECT count(*) FROM t1, t2 WHERE y = c;
SELECT count(*) FROM t1, t3 WHERE y = c;
